/* Match WindowServer's straight-alpha ARGB8888 compositing. */
static inline uint32_t
nxu_pointer_cursor_blend(uint32_t background, uint32_t source)
{
	uint32_t alpha = source >> 24;

	if (alpha == 0U) {
		return background;
	}

	uint32_t inverse = 255U - alpha;
	uint32_t result = 0xFF000000U;

	for (uint32_t shift = 0U; shift < 24U; shift += 8U) {
		uint32_t channel =
			(((source >> shift) & 255U) * alpha + ((background >> shift) & 255U) * inverse + 127U) / 255U;
		result |= channel << shift;
	}

	return result;
}

